/**
 * Modal. Base UI Dialog skinned as an Echo device
 * panel: molded chassis surface behind convex glass. Colors compose
 * var(--echo-*); the popup's transform/opacity is owned by GSAP (useGsapPresence),
 * so this file sets NO transition on the popup — only on the backdrop.
 */

.echo-modal__backdrop {
  position: fixed;
  inset: 0;
  z-index: var(--echo-z-overlay, 200);
  background: color-mix(in oklab, var(--echo-well) 72%, transparent);
  backdrop-filter: blur(2px);
  opacity: 0;
  transition: opacity var(--echo-duration-sweep) ease;
}
.echo-modal__backdrop[data-open] {
  opacity: 1;
}
.echo-modal__backdrop[data-ending-style] {
  opacity: 0;
}

.echo-modal__popup {
  position: fixed;
  z-index: var(--echo-z-modal, 210);
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  width: min(92vw, 30rem);
  padding: var(--echo-space-10);
  border-radius: var(--echo-radius-2xl);
  color: var(--echo-text);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);

  background: linear-gradient(155deg, var(--echo-cap) 0%, var(--echo-surface) 46%, var(--echo-cap-shadow) 100%);
  box-shadow:
    inset 0 1.5px 0 rgb(255 255 255 / calc(0.08 * var(--echo-gloss, 1))),
    inset 0 0 0 1px var(--echo-seam),
    0 calc(40px + 50px * var(--air, 0)) calc(80px + 70px * var(--air, 0)) -24px
      color-mix(in oklab, var(--echo-cast-ink, black) calc(0.8 * var(--echo-shade, 1) * 100%), transparent);
  /* GSAP owns transform + opacity; do not add a transition here. */
  will-change: transform, opacity;
}

.echo-modal__popup[data-size="sm"] {
  width: min(92vw, 22rem);
}
.echo-modal__popup[data-size="lg"] {
  width: min(94vw, 42rem);
}

.echo-modal__popup:focus-visible {
  outline: none;
}

.echo-modal__title {
  margin: 0 0 var(--echo-space-3);
  font-size: var(--echo-text-lg);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-tight, -0.01em);
}

.echo-modal__desc {
  margin: 0 0 var(--echo-space-8);
  color: var(--echo-text-dim);
  font-size: var(--echo-text-md);
  line-height: var(--echo-leading-body, 1.55);
}

.echo-modal__body {
  font-size: var(--echo-text-md);
  line-height: var(--echo-leading-body, 1.55);
}

.echo-modal__footer {
  display: flex;
  justify-content: flex-end;
  gap: var(--echo-space-5);
  margin-top: var(--echo-space-10);
}

.echo-modal__close {
  position: absolute;
  top: 14px;
  inset-inline-end: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: calc(28px * var(--echo-density, 1));
  border: 0;
  border-radius: var(--echo-radius-md);
  cursor: pointer;
  color: var(--echo-text-dim);
  background: color-mix(in oklab, var(--echo-well) 60%, transparent);
  font-size: var(--echo-text-md);
  line-height: var(--echo-leading-none, 1);
}
@media (hover: hover) {
  .echo-modal__close:hover {
    color: var(--echo-text);
  }
}
.echo-modal__close:focus-visible {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  box-shadow: 0 0 0 2px var(--echo-accent-ink, var(--echo-accent-glow));
}

@media (prefers-reduced-motion: reduce) {
  .echo-modal__backdrop {
    transition-duration: var(--echo-duration-tick);
  }
}

/*
 * Coarse-pointer targets.
 *
 * These already clear WCAG 2.2 2.5.8's 24px. This is the other
 * threshold: the 44px both platform guidelines use, which is about a
 * fingertip rather than about conformance.
 *
 * Gated on `@media (pointer: coarse)` so the desktop rendering does not move
 * — these are "passing AA but under the
 * platform guideline", not broken. Pagination is first among them because
 * people tap it repeatedly, which is exactly when a 30px target starts
 * costing mis-taps.
 */
@media (pointer: coarse) {
  .echo-modal__close {
    width: 44px;
    height: 44px;
  }
}

"use client";

/**
 * Modal. Behavior from Base UI's Dialog (focus
 * trap, Esc, scroll-lock, a11y wiring); skin + motion + sound from Echo. Enter
 * uses motion.summon, exit is a GSAP tween that completes BEFORE unmount via
 * useGsapPresence + Base UI's actionsRef. Sound.transition plays on open.
 *
 * NOTE: the package is `@base-ui/react`, NOT `@base-ui-components/react`.
 */
import * as React from "react";
import { isValidElement, type ReactElement, type ReactNode } from "react";
import { Dialog } from "@base-ui/react/dialog";
import { liquidBloom, useGsapPresence } from "echo-ui-core/presence";
import type { EchoPortalContainer } from "echo-ui-core/types";
import { useSoundOptional } from "echo-ui-core/sound";
import { usePressable } from "echo-ui-core/tactile";
import "./modal.css";

export type ModalSize = "sm" | "md" | "lg";

export interface ModalProps {
  /** Element or text that opens the modal (rendered as the Dialog trigger). */
  trigger?: ReactNode;
  title?: ReactNode;
  description?: ReactNode;
  children?: ReactNode;
  footer?: ReactNode;
  size?: ModalSize;
  /** Show the corner close button. Default true. */
  showClose?: boolean;
  /** Start opened (uncontrolled). */
  defaultOpen?: boolean;
  /**
   * Where the popup mounts. Defaults to <body>. Pass an element inside a
   * scoped theme (`createEchoTheme(seed, { selector })`) and the popup wears
   * that theme too — mounted on <body>, it can only read the :root one.
   */
  container?: EchoPortalContainer;
}

/**
 * The element to render as the trigger, or null to wrap `trigger` in a plain
 * button. In development, an element passed from a server component can arrive
 * as a lazy reference, which `isValidElement` rejects, so it got wrapped in a
 * second button. `use` unwraps it, as Radix's Slot does. React 18 has
 * neither `use` nor server components, so it never meets one. The key is built
 * at runtime so bundlers don't warn about a missing export on React 18.
 */
function useTriggerElement(trigger: ReactNode): ReactElement | null {
  if (isValidElement(trigger)) return trigger;
  const use = (React as unknown as Record<string, unknown>)[" use ".trim()];
  if (
    typeof use === "function" &&
    typeof trigger === "object" &&
    trigger !== null &&
    (trigger as { $$typeof?: symbol }).$$typeof === Symbol.for("react.lazy")
  ) {
    const payload = (trigger as { _payload?: unknown })._payload;
    if (payload && typeof (payload as PromiseLike<unknown>).then === "function") {
      const resolved: unknown = use(payload);
      if (isValidElement(resolved)) return resolved;
    }
  }
  return null;
}


export function Modal({
  trigger,
  title,
  description,
  children,
  footer,
  size = "md",
  showClose = true,
  defaultOpen = false,
  container,
}: ModalProps) {
  const triggerElement = useTriggerElement(trigger);
  // Liquid bloom: it swells out of a pill in the middle of the room.
  const presence = useGsapPresence({ exit: "summon", defaultOpen, animate: liquidBloom });
  const sound = useSoundOptional();

  const handleOpenChange = (nextOpen: boolean, details: Dialog.Root.ChangeEventDetails) => {
    if (nextOpen) sound?.play("transition");
    presence.onOpenChange(nextOpen, details);
  };

  return (
    <Dialog.Root
      open={presence.open}
      onOpenChange={handleOpenChange}
      actionsRef={presence.actionsRef as React.RefObject<Dialog.Root.Actions | null>}
    >
      {trigger != null &&
        (triggerElement ? (
          <Dialog.Trigger render={triggerElement} />
        ) : (
          <Dialog.Trigger>{trigger}</Dialog.Trigger>
        ))}

      <Dialog.Portal container={container}>
        <Dialog.Backdrop className="echo-modal__backdrop" />
        <Dialog.Popup ref={presence.popupRef} className="echo-modal__popup" data-size={size}>
          {title != null ? <Dialog.Title className="echo-modal__title">{title}</Dialog.Title> : null}
          {description != null ? (
            <Dialog.Description className="echo-modal__desc">{description}</Dialog.Description>
          ) : null}
          {children != null ? <div className="echo-modal__body">{children}</div> : null}
          {footer != null ? <div className="echo-modal__footer">{footer}</div> : null}
          {showClose ? (
            <ModalCloseKey />
          ) : null}
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

/* The close key presses like the library's keys: a small one, 1px down. */
function ModalCloseKey() {
  const press = usePressable<HTMLButtonElement>({}, { lift: 0, travel: 1, tilt: 0 });
  return (
    <Dialog.Close className="echo-modal__close" aria-label="Close" {...press}>
      ✕
    </Dialog.Close>
  );
}

/**
 * echo-modal — Base UI Dialog skinned as an Echo device panel.
 */
export { Modal } from "./modal";
export type { ModalProps, ModalSize } from "./modal";
